import { API_URL } from './config.js';
const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let fx=null;
const money=(cents,currency='MXN')=>new Intl.NumberFormat('zh-CN',{style:'currency',currency,minimumFractionDigits:2}).format(cents/100);
const priced=p=>Number.isInteger(p.price_cents)&&p.price_cents>=0;
const dual=(mxn,cny)=>`<strong>${money(mxn)} <small>MXN</small></strong><small class="cny-money">${cny===null?'人民币折算暂不可用':`≈ ${money(cny,'CNY')} CNY`}</small>`;
function cartAmount(){let mxn=0,cny=0;for(const p of lines()){if(!priced(p))return null;mxn+=p.price_cents*cart[p.id];if(fx)cny+=Math.round(p.price_cents*fx.rate)*cart[p.id];}return{mxn,cny:fx?cny:null};}
const fxNotice=()=>fx?`<span>汇率：1 MXN ≈ ${fx.rate} CNY · ${esc(fx.date)} · Frankfurter 最新参考汇率</span>`:'<span>人民币汇率暂不可用，请刷新后再提交</span>';
function orderMoney(o){if(o.total_mxn_cents==null)return '<p class="muted">历史订单未记录价格，金额待确认</p>';return `<div class="order-total"><span>订单合计</span><div>${dual(o.total_mxn_cents,o.total_cny_cents)}</div></div><p class="muted fx-note">下单汇率：1 MXN ≈ ${o.fx_rate} CNY · ${esc(o.fx_date)} · ${esc(o.fx_source||'Frankfurter')}，人民币为参考金额</p>`;}
function orderItemRows(o){return `<div class="table-wrap"><table class="order-detail-table"><thead><tr><th>商品</th><th>单价 / 单位</th><th>数量</th><th>小计</th></tr></thead><tbody>${o.items.map(i=>`<tr><td>${esc(i.name)}</td><td>${i.unit_price_cents==null?'未记录':dual(i.unit_price_cents,i.unit_price_cny_cents)}<small class="cny-money">/ ${esc(i.unit)}</small></td><td>${i.quantity} ${esc(i.unit)}</td><td>${i.line_total_mxn_cents==null?'待确认':dual(i.line_total_mxn_cents,i.line_total_cny_cents)}</td></tr>`).join('')}</tbody></table></div>${orderMoney(o)}`;}
const orderStatus={pending:'待配送',cancelled:'已取消',fulfilled:'已完成',rejected:'已拒绝配送'};
const regions=['将军镇','华富山','波瓦达波','机场','阿波达卡'];
const icons={'上海青':'🥬','西红柿':'🍅','土豆':'🥔','胡萝卜':'🥕','黄瓜':'🥒','西兰花':'🥦','大白菜':'🥬','生姜':'🫚','大蒜':'🧄','小葱':'🌱','香菜':'🌿','白萝卜':'🥕'};
let products=[],cart={},staff=null,token=sessionStorage.getItem('market-token')||'',tab='orders',selectedRegion='',orders=[],orderSearch='',statusFilter='pending',search='',pendingId=null,pendingReceipt=null;
const receiptCode=()=>{const alphabet='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';return Array.from(crypto.getRandomValues(new Uint8Array(10)),v=>alphabet[v%32]).join('');};
const formatCode=code=>`${code.slice(0,5)}-${code.slice(5)}`;
function savedReceipts(){try{const data=JSON.parse(localStorage.getItem('market-receipts')||'[]');return Array.isArray(data)?data:[];}catch{return[];}}
function rememberReceipt(code){const saved=savedReceipts().filter(x=>x!==code);saved.unshift(code);localStorage.setItem('market-receipts',JSON.stringify(saved.slice(0,50)));}
try{cart=JSON.parse(localStorage.getItem('market-cart')||'{}');if(!cart||Array.isArray(cart)||typeof cart!=='object')cart={};}catch{cart={};}
const total=()=>Object.values(cart).reduce((a,b)=>a+(Number.isInteger(b)&&b>0?b:0),0);
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4200);}
async function api(action,data={}){
  const multipart=data instanceof FormData;if(multipart)data.set('action',action);
  const response=await fetch(API_URL,{method:'POST',headers:{...(!multipart?{'Content-Type':'application/json'}:{}),...(token?{Authorization:`Bearer ${token}`}:{})},body:multipart?data:JSON.stringify({action,...data}),signal:AbortSignal.timeout(multipart?60000:25000)});
  let result;try{result=await response.json();}catch{throw new Error('服务暂不可用，请稍后重试');}
  if(!response.ok){if(response.status===401&&action!=='login'){logout();}throw new Error(result.error||'请求失败');}return result;
}
const lines=()=>products.filter(p=>cart[p.id]>0);
function saveCart(){localStorage.setItem('market-cart',JSON.stringify(cart));pendingId=null;pendingReceipt=null;updateCount();}
function updateCount(){ $('#nav-count').textContent=total();const show=(location.hash==='#shop'||!location.hash)&&total()>0;$('#mobile-cart').innerHTML=show?`<div><strong>已选 ${lines().length} 种蔬菜</strong><br><small>${cartAmount()?dual(cartAmount().mxn,cartAmount().cny):'含未定价商品'}</small></div><button class="primary" data-action="checkout">查看菜篮 →</button>`:''; }
function quantity(p){const n=cart[p.id]||0;return `<div class="qty"><button type="button" data-action="minus" data-id="${p.id}" aria-label="减少${esc(p.name)}" ${n===0?'disabled':''}>−</button><span aria-live="polite">${n}</span><button type="button" class="plus" data-action="plus" data-id="${p.id}" aria-label="增加${esc(p.name)}" ${n>=999||!priced(p)?'disabled':''}>+</button></div>`;}
function basketRows(edit=false){return lines().map(p=>`<div class="basket-row"><div><b>${esc(p.name)}</b><small>${priced(p)?`${money(p.price_cents)} MXN / ${esc(p.unit)}`:'待定价'}</small>${edit?quantity(p):`<small>${cart[p.id]} ${esc(p.unit)}</small>`}</div><div class="line-money">${priced(p)?dual(p.price_cents*cart[p.id],fx?Math.round(p.price_cents*fx.rate)*cart[p.id]:null):'待定价'}</div></div>`).join('');}
function basket(){const amount=cartAmount();return `<aside class="basket"><div class="section-title"><h2>我的菜篮</h2><span class="product-count">${lines().length} 种</span></div>${lines().length?basketRows():`<div class="basket-empty"><div>♧</div>菜篮还是空的<br>挑几样新鲜蔬菜吧</div>`}<div class="basket-foot"><div class="order-total"><span>合计</span><div>${amount?dual(amount.mxn,amount.cny):'含未定价商品'}</div></div><button class="primary full" data-action="checkout" ${total()&&amount?'':'disabled'}>填写收货信息 →</button><small>以MXN计价，人民币按最新参考汇率折算</small></div></aside>`;}
function productCards(){const filtered=products.filter(p=>p.name.includes(search));return filtered.length?filtered.map(p=>`<article class="product"><div class="produce-art">${p.image_url?`<img src="${esc(p.image_url)}" alt="${esc(p.name)}" loading="lazy">`:`<span aria-hidden="true">${icons[p.name]||'🌿'}</span>`}</div><h3>${esc(p.name)}</h3><span class="muted">按${esc(p.unit)}选购</span><div class="product-price">${priced(p)?dual(p.price_cents,fx?Math.round(p.price_cents*fx.rate):null):'<strong class="muted">待定价</strong>'}</div><div class="product-bottom"><span class="product-count">每 ${esc(p.unit)}</span>${quantity(p)}</div></article>`).join(''):`<div class="empty">${products.length?'没有找到对应蔬菜':'暂时没有上架商品，请稍后再来。'}</div>`;}
function shop(){ $('#main').innerHTML=`<section class="hero"><div><div class="eyebrow">FROM THE MARKET, TO YOUR HOME</div><h1>一篮新鲜，<br>刚好是家的味道。</h1><p>挑选喜欢的蔬菜，把今天的好好吃饭安排上。</p><span class="hero-tag">新鲜选购 / 邻里配送</span></div><div class="hero-art" aria-hidden="true"><span>🥕</span><span>🥬</span><span>🍅</span></div></section><div class="region-strip"><span>⌖ 配送区域</span>${regions.map(r=>`<b>${r}</b>`).join('<span>·</span>')}</div><div class="fx-banner">${fxNotice()}<button class="small-button" data-action="refresh-prices">刷新价格与汇率</button></div><div class="shop-layout"><section><div class="section-head"><h2>逛逛菜市场 <small>${products.length} 种当季好菜</small></h2><input class="search" id="search" type="search" placeholder="搜索你想吃的蔬菜" aria-label="搜索蔬菜" value="${esc(search)}"></div><div class="products" id="products">${productCards()}</div></section>${basket()}</div>`;updateCount();}
function checkout(){
  $('#main').innerHTML=`<div class="eyebrow">YOUR FRESH BASKET</div><h1>把新鲜带回家</h1><p class="muted">核对菜篮，留下收货信息。无需注册，即可提交采购需求。</p>${total()?`<div class="checkout-grid"><section class="panel"><h2>收货信息</h2><form id="order-form"><div class="fields"><label class="field">收货人<input name="customer" autocomplete="name" maxlength="60" required placeholder="怎么称呼您"></label><label class="field">联系方式<input name="phone" type="tel" autocomplete="tel" minlength="5" maxlength="40" required placeholder="电话或 WhatsApp"></label></div><label class="field">居住区域<select name="region" required><option value="">请选择配送区域</option>${regions.map(r=>`<option>${r}</option>`).join('')}</select></label><label class="field">详细收货地址<input name="address" autocomplete="street-address" minlength="5" maxlength="300" required placeholder="街道、门牌号、小区及其他收货信息"></label><div class="notice">提交后，供应商将根据您填写的联系方式确认供货及配送。</div><p class="error" id="form-error" role="alert"></p><button class="primary full" type="submit" ${fx&&cartAmount()?'':'disabled'}>确认提交采购需求 →</button><p class="muted">您的地址及联系方式仅用于订单履约。连续取消3次会限制所在网络访问，共享Wi-Fi用户可能受到影响。</p></form></section><section class="panel"><div class="section-title"><h2>已选蔬菜</h2><button class="small-button danger" data-action="clear-cart">清空</button></div>${basketRows(true)}<div class="order-total"><span>订单合计</span><div>${cartAmount()?dual(cartAmount().mxn,cartAmount().cny):'含未定价商品'}</div></div><div class="fx-banner">${fxNotice()}<button class="small-button" data-action="refresh-prices">刷新价格与汇率</button></div><p class="muted">人民币按单价折算至分后乘以数量，各项相加；以MXN金额为准。</p><p class="muted">${lines().length} 种蔬菜 · 共 ${total()} 个计量单位</p><a href="#shop" class="muted">← 继续逛逛</a></section></div>`:`<section class="panel empty"><p>菜篮还是空的，先挑选几样蔬菜吧。</p><button class="primary" data-action="shop">去选菜 →</button></section>`}`;updateCount();}
function login(){ $('#main').innerHTML=`<section class="panel login"><div class="eyebrow">MARKET WORKSPACE</div><h1>欢迎回来</h1><p class="muted">管理员与供应商，请使用后台账号登录。</p><form id="login-form"><label class="field">账号<input name="username" autocomplete="username" required maxlength="30" placeholder="请输入后台账号"></label><label class="field">密码<input name="password" type="password" autocomplete="current-password" required maxlength="128" placeholder="请输入密码"></label><p class="error" id="form-error" role="alert"></p><button type="submit" class="primary full">登录后台 →</button></form><div class="notice">顾客无需登录，可直接前往菜市场选菜。</div></section>`;}
function passwordForm(forced=false){ $('#main').innerHTML=`<section class="panel login"><div class="eyebrow">ACCOUNT SECURITY</div><h1>${forced?'先设置您的新密码':'修改密码'}</h1><p class="muted">${forced?'首次登录必须修改初始密码，完成后才能进入后台。':'修改成功后请使用新密码重新登录。'}</p><form id="password-form"><label class="field">原密码<input type="password" name="current" autocomplete="current-password" required maxlength="128"></label><label class="field">新密码<input type="password" name="password" autocomplete="new-password" minlength="8" maxlength="128" required placeholder="至少8位，包含字母和数字"></label><label class="field">再次输入新密码<input type="password" name="confirm" autocomplete="new-password" minlength="8" maxlength="128" required></label><p id="form-error" class="error" role="alert"></p><button type="submit" class="primary full">保存新密码</button></form><button class="full" style="margin-top:12px" data-action="${forced?'logout':'back-admin'}">${forced?'退出登录':'返回后台'}</button></section>`;}
function adminShell(){ $('#main').innerHTML=`<div class="section-title"><div><div class="eyebrow">MARKET WORKSPACE</div><h1>${staff.role==='admin'?'管理工作台':'供应商工作台'}</h1></div><div class="toolbar"><span class="muted">${esc(staff.username)}</span><button class="small-button" data-action="password">修改密码</button><button class="small-button" data-action="logout">退出</button></div></div><p class="muted">按区域查看客户需求，让备菜与配送井井有条。</p><div class="tabs"><button data-tab="orders" class="${tab==='orders'?'active':''}">订单与备菜</button><button data-tab="products" class="${tab==='products'?'active':''}">商品与单价</button>${staff.role==='admin'?`<button data-tab="supplier" class="${tab==='supplier'?'active':''}">供应商账号</button><button data-tab="rules" class="${tab==='rules'?'active':''}">访问封锁</button>`:''}</div><div id="admin-content"><p class="muted">正在加载…</p></div>`;}
async function admin(){if(!staff){login();return;}if(staff.must_change){passwordForm(true);return;}adminShell();try{if(tab==='orders')await renderOrders();else if(tab==='products')renderProductAdmin();else if(tab==='supplier')await renderSupplier();else await renderRules();}catch(e){$('#admin-content').innerHTML=`<p class="error">${esc(e.message)}</p><button data-action="back-admin">重新加载</button>`;}}
async function renderOrders(){
  const data=await api('orders',{region:selectedRegion});orders=data.orders;
  const needle=orderSearch.toLowerCase().replace(/-/g,'');
  const visible=orders.filter(o=>(!statusFilter||o.status===statusFilter)&&(!needle||[o.customer,o.phone,o.id,o.receipt_code||''].some(v=>v.toLowerCase().replace(/-/g,'').includes(needle)))); 
  const summary=new Map();for(const o of orders.filter(o=>o.status==='pending'))for(const i of o.items){const key=JSON.stringify([i.id,i.name,i.unit]);const row=summary.get(key)||{...i,quantity:0};row.quantity+=i.quantity;summary.set(key,row);}
  $('#admin-content').innerHTML=`<div class="toolbar"><b>配送区域</b><select id="filter-region" aria-label="按配送区域筛选"><option value="">全部区域</option>${regions.map(r=>`<option ${r===selectedRegion?'selected':''}>${r}</option>`).join('')}</select><select id="filter-status" aria-label="按订单状态筛选"><option value="pending" ${statusFilter==='pending'?'selected':''}>待配送</option><option value="fulfilled" ${statusFilter==='fulfilled'?'selected':''}>已完成</option><option value="cancelled" ${statusFilter==='cancelled'?'selected':''}>客户已取消</option><option value="rejected" ${statusFilter==='rejected'?'selected':''}>已拒绝配送</option><option value="" ${statusFilter===''?'selected':''}>全部状态</option></select><button class="small-button" data-action="refresh">刷新订单</button><span class="muted">备菜汇总仅包含${selectedRegion||'所有区域'}的待配送订单</span></div><div class="stat-grid"><div class="stat">采购订单<strong>${orders.filter(o=>o.status==='pending').length}</strong>笔待配送订单</div><div class="stat">待备商品<strong>${summary.size}</strong>种商品及单位</div><div class="stat">覆盖区域<strong>${new Set(orders.filter(o=>o.status==='pending').map(o=>o.region)).size}</strong>个配送区域</div></div><section class="panel"><h2>备菜数量汇总</h2><p class="muted">不同名称或单位单独统计，数量按商品计量单位合计。</p>${summary.size?`<div class="table-wrap"><table><thead><tr><th>商品名称</th><th>采购数量</th><th>单位</th></tr></thead><tbody>${[...summary.values()].map(i=>`<tr><td>${esc(i.name)}</td><td><b>${i.quantity}</b></td><td>${esc(i.unit)}</td></tr>`).join('')}</tbody></table></div>`:`<p class="empty">该区域暂时没有订单</p>`}</section><section class="panel"><h2>客户订单明细</h2><form id="order-search-form" class="inline-form"><label class="field">${staff.role==='admin'?'搜索查询码、姓名或联系方式':'搜索姓名或联系方式'}<input name="query" value="${esc(orderSearch)}" placeholder="输入关键词"></label><button type="submit">搜索</button></form>${visible.map(o=>`<details class="order-card order-fold"><summary><div class="order-summary-head"><div><b>${esc(o.customer)}</b><div class="order-state"><span class="pill">${esc(o.region)} · ${esc(orderStatus[o.status]||o.status)}</span></div></div><div class="summary-amount">${o.total_mxn_cents==null?'金额待确认':`${money(o.total_mxn_cents)} <small>MXN</small>`}</div><div class="order-contact"><small>客户联系方式</small><strong>${esc(o.phone)}</strong></div></div><span class="fold-cue"><span class="when-closed">展开明细</span><span class="when-open">收起明细</span><span aria-hidden="true">⌄</span></span></summary><div class="order-expanded"><p>${esc(o.address)}</p>${orderItemRows(o)}<p class="muted">${new Date(o.created_at).toLocaleString('zh-CN',{timeZone:'America/Monterrey',hour12:false})}（蒙特雷时间）<br>订单号：${esc(o.id)}</p>${staff.role==='admin'?`<p class="muted">查询码：<b>${esc(formatCode(o.receipt_code))}</b></p>`:''}${o.status==='rejected'?`<div class="rejection-notice"><b>拒绝配送原因</b><p>${esc(o.rejection_reason)}</p><small>客户可凭查询码查看此原因</small></div>`:''}${o.status==='pending'?`<div class="order-actions"><button class="small-button" data-action="fulfill" data-id="${o.id}">标记配送完成</button><button class="small-button danger" data-action="reject-order" data-id="${o.id}">拒绝配送 / 删除订单</button></div>`:''}</div></details>`).join('')||'<p class="empty">客户提交后，订单会显示在这里。</p>'}</section><dialog id="reject-dialog"><form id="reject-order-form"><h2>拒绝配送 / 删除订单</h2><p class="muted">订单将移出待配送和备菜清单，客户仍能查看已拒绝状态及您填写的原因。</p><input type="hidden" name="order_id"><label class="field">拒绝原因（客户可见，必填）<textarea name="reason" required maxlength="500" rows="4" placeholder="例如：该区域暂时无法配送，或商品缺货"></textarea></label><p class="error" id="form-error" role="alert"></p><div class="order-actions"><button class="danger" type="submit">确认拒绝配送</button><button type="button" data-action="close-reject">返回</button></div></form></dialog>`;
}
let imagePreviewURL='';
function renderProductAdmin(){
  $('#admin-content').innerHTML=`<section class="panel"><div class="fx-banner">${fxNotice()}<button class="small-button" data-action="refresh-prices">刷新价格与汇率</button></div><div class="section-title"><h2>在售商品 <span class="muted">${products.length} 种</span></h2>${staff?.role==='supplier'?'':'<button class="primary" data-action="new-product">＋ 新增商品</button>'}</div><div class="table-wrap"><table><thead><tr><th>图片</th><th>名称</th><th>单位</th><th>单价 MXN</th><th>折合 CNY</th>${staff?.role==='supplier'?'':'<th>操作</th>'}</tr></thead><tbody>${products.map(p=>`<tr><td>${p.image_url?`<img class="product-thumb" src="${esc(p.image_url)}" alt="${esc(p.name)}" loading="lazy">`:'暂无图片'}</td><td>${esc(p.name)}</td><td>${esc(p.unit)}</td><td>${priced(p)?money(p.price_cents):'待定价'}</td><td>${priced(p)&&fx?money(Math.round(p.price_cents*fx.rate),'CNY'):'—'}</td>${staff?.role==='supplier'?'':`<td><button data-action="edit-product" data-id="${p.id}">编辑</button><button class="danger" data-action="delete-product" data-id="${p.id}">删除</button></td>`}</tr>`).join('')}</tbody></table></div><p class="muted">商品删除后将不再显示在菜市场，历史订单中的商品信息仍会保留。</p></section><dialog id="product-dialog" class="product-dialog" aria-labelledby="product-editor-title"></dialog>`;
}
function openProductEditor(edit=null){
  if(staff?.role==='supplier')return;
  if(imagePreviewURL){URL.revokeObjectURL(imagePreviewURL);imagePreviewURL='';}
  const dialog=$('#product-dialog');
  dialog.innerHTML=`<div class="section-title"><h2 id="product-editor-title">${edit?'编辑商品':'新增商品'}</h2><button type="button" class="small-button" data-action="cancel-edit" aria-label="关闭商品编辑">关闭</button></div><form id="product-form"><input type="hidden" name="id" value="${edit?.id||''}"><div class="fields"><label class="field">商品名称<input name="name" maxlength="60" required value="${esc(edit?.name||'')}" placeholder="例如：上海青"></label><label class="field">计量单位<input name="unit" maxlength="20" required value="${esc(edit?.unit||'')}" placeholder="例如：把 / 公斤 / 颗"></label></div><label class="field price-field">单价（墨西哥比索 MXN / 单位）<input name="price" type="number" min="0" max="999999.99" step="0.01" required inputmode="decimal" value="${edit&&priced(edit)?(edit.price_cents/100).toFixed(2):''}" placeholder="例如：25.50"></label><div class="product-image-editor"><div id="image-preview" class="image-preview">${edit?.image_url?`<img src="${esc(edit.image_url)}" alt="当前商品图片">`:'<span>暂无图片</span>'}</div><div><label class="field">商品图片（可选）<input type="file" id="product-image" name="image" accept="image/jpeg,image/png,image/webp"></label><p class="muted">选择 JPG、PNG 或 WebP 图片，最大5MB。保存后客户会在商品卡片上看到图片。</p>${edit?.image_url?'<label class="remove-image"><input type="checkbox" name="remove_image" value="1"> 移除当前图片（选择新图时优先使用新图）</label>':''}</div></div><p class="error" id="form-error" role="alert"></p><button class="primary" type="submit">${edit?'保存修改':'新增商品'}</button><button type="button" data-action="cancel-edit">取消</button></form>`;
  dialog.showModal();dialog.querySelector('[name="name"]').focus();
}
async function renderSupplier(){const {supplier}=await api('supplier');$('#admin-content').innerHTML=`<section class="panel" style="max-width:650px"><h2>${supplier?'管理供应商账号':'设置供应商账号'}</h2><p class="muted">系统仅保留一个管理员和一个供应商。${supplier?`当前供应商：${esc(supplier.username)}。重新保存将重设其初始密码。`:'请为供应商设置账号和初始密码。'}</p><form id="supplier-form"><label class="field">供应商账号<input name="username" required pattern="[a-zA-Z][a-zA-Z0-9_-]{2,29}" maxlength="30" value="${esc(supplier?.username||'')}" placeholder="3–30位字母、数字、下划线或短横线"></label><label class="field">${supplier?'重设初始密码':'初始密码'}<input name="password" type="password" autocomplete="new-password" minlength="8" maxlength="128" required placeholder="至少8位，包含字母和数字"></label><div class="notice">供应商首次登录或密码被重设后，必须自行修改密码才能查看订单。请将账号和初始密码单独告知供应商。</div><p class="error" id="form-error" role="alert"></p><button class="primary" type="submit">保存供应商账号</button></form></section>`;}
function logout(){token='';staff=null;sessionStorage.removeItem('market-token');if(location.hash==='#admin')login();}
async function renderRules(){const {rules}=await api('ip-rules');$('#admin-content').innerHTML=`<section class="panel"><h2>网络访问限制</h2><p class="muted">连续取消3次自动封锁。完成配送会清零连续取消次数，已封锁网络仍需管理员手动解除。网络仅保存哈希标识，不显示原始IP。</p>${rules.length?rules.map(r=>`<article class="order-card"><header><b>${r.blocked?'已封锁':'尚未封锁'} · 连续取消 ${r.cancel_streak} 次</b></header><p class="muted" style="overflow-wrap:anywhere">网络标识：${esc(r.ip_hash)}</p><button class="small-button" data-action="unblock" data-ip="${esc(r.ip_hash)}">解除限制并清零</button></article>`).join(''):'<p class="empty">暂时没有限制记录。</p>'}</section>`;}
function myOrders(){const saved=savedReceipts();$('#main').innerHTML=`<div class="eyebrow">YOUR PRIVATE ORDERS</div><h1>我的订单</h1><p class="muted">输入专属查询码，查看您的采购需求。订单不会公开展示。</p><section class="panel"><form id="lookup-form" class="inline-form"><label class="field">专属查询码<input name="receipt" maxlength="11" minlength="10" required autocomplete="off" autocapitalize="characters" placeholder="ABCDE-23456"></label><button class="primary" type="submit">查询订单</button></form><p id="form-error" class="error" role="alert"></p><div class="notice">查询码相当于订单钥匙，请妥善保管，不要发给其他人。清除浏览器数据后，可凭查询码在任意设备查询。</div></section>${saved.length?`<section class="panel"><h2>本机保存的订单</h2><p class="muted">仅此浏览器可见。共用设备使用后，可清除本机记录。</p>${saved.map(code=>`<div class="basket-row"><b>${esc(formatCode(code))}</b><button class="small-button" data-action="lookup" data-code="${esc(code)}">查看订单</button></div>`).join('')}<button class="small-button danger" style="margin-top:18px" data-action="forget-orders">清除本机记录</button></section>`:''}<div id="my-order-result"></div>`;}
async function lookup(code){const {order:o}=await api('my-order',{receipt:code});rememberReceipt(code.replace(/-/g,'').toUpperCase());$('#my-order-result').innerHTML=`<section class="panel"><h2>您的采购需求</h2><article class="order-card"><header><div><b>${esc(o.customer)}</b><div class="order-state"><span class="pill">${esc(o.region)} · ${esc(orderStatus[o.status]||o.status)}</span></div></div><div class="order-contact"><small>客户联系方式</small><strong>${esc(o.phone)}</strong></div></header><p>${esc(o.address)}</p>${orderItemRows(o)}<p class="muted">${new Date(o.created_at).toLocaleString('zh-CN',{timeZone:'America/Monterrey',hour12:false})}（蒙特雷时间）<br>订单编号：${esc(o.id)}</p></article><div class="notice">${o.status==='rejected'?'订单已被拒绝配送，不再计入备菜需求。':o.status==='cancelled'?'订单已取消，不再计入备菜需求。':o.status==='fulfilled'?'供应商已标记配送完成。':'已提交，等待供应商联系确认供货及配送。'}</div><p>订单状态：<b>${esc(orderStatus[o.status]||o.status)}</b></p>${o.status==='rejected'?`<div class="rejection-notice"><b>拒绝配送原因</b><p>${esc(o.rejection_reason)}</p></div>`:''}${o.status==='pending'?`<p class="muted">连续取消3次将限制所在网络访问，共享Wi-Fi的其他用户也可能受到影响。</p><button class="danger" data-action="cancel-order" data-code="${esc(code)}">取消此订单</button>`:''}</section>`;$('#my-order-result').scrollIntoView({block:'start',behavior:'smooth'});}
function route(){const view=location.hash.slice(1)||'shop';document.querySelectorAll('[data-nav]').forEach(a=>{const on=a.dataset.nav===view;a.classList.toggle('active',on);if(on)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#breadcrumb').textContent=`菜市场 / ${{shop:'挑选蔬菜',cart:'我的菜篮',orders:'我的订单',admin:'登录'}[view]||'挑选蔬菜'}`;$('#mobile-cart').innerHTML='';if(view==='cart')checkout();else if(view==='admin')admin();else if(view==='orders')myOrders();else shop();}
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;$('#products').innerHTML=productCards();}});
document.addEventListener('change',async e=>{if(e.target.id==='product-image'){const file=e.target.files[0];if(imagePreviewURL)URL.revokeObjectURL(imagePreviewURL);imagePreviewURL='';if(file){if(file.size>5*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type)){e.target.value='';$('#form-error').textContent='请选择不超过5MB的 JPG、PNG 或 WebP 图片';return;}imagePreviewURL=URL.createObjectURL(file);$('#image-preview').innerHTML=`<img src="${imagePreviewURL}" alt="待上传图片预览">`;$('#form-error').textContent='';}}if(e.target.id==='filter-region'||e.target.id==='filter-status'){if(e.target.id==='filter-region')selectedRegion=e.target.value;else statusFilter=e.target.value;try{await renderOrders();}catch(err){toast(err.message);}}});
document.addEventListener('click',async e=>{
  const el=e.target.closest('button');if(!el)return;
  if(el.dataset.tab){tab=el.dataset.tab;admin();return;}
  const action=el.dataset.action,id=el.dataset.id;
  if(action==='refresh-prices'){el.disabled=true;const form=$('#order-form');const data=form?Object.fromEntries(new FormData(form)):null;try{const values=await Promise.all([api('fx'),api('products')]);fx=values[0];products=values[1].products;route();if(data&&$('#order-form'))for(const [key,value]of Object.entries(data))$('#order-form').elements[key].value=value;toast('价格与汇率已刷新');}catch(err){toast(err.message);el.disabled=false;}return;}
  if(action==='plus'||action==='minus'){if(action==='plus'&&!priced(products.find(p=>p.id===id)))return;cart[id]=Math.min(999,Math.max(0,(cart[id]||0)+(action==='plus'?1:-1)));if(!cart[id])delete cart[id];saveCart();if(location.hash==='#cart'){const form=$('#order-form');const data=form?Object.fromEntries(new FormData(form)):null;checkout();if(data)for(const [k,v]of Object.entries(data))if($('#order-form')?.elements[k])$('#order-form').elements[k].value=v;}else{$('#products').innerHTML=productCards();$('.basket').outerHTML=basket();}return;}
  if(action==='checkout')location.hash='cart';
  if(action==='shop')location.hash='shop';
  if(action==='cancel-order'&&confirm('确定取消这笔订单？连续取消3次会封锁所在网络。')){el.disabled=true;try{const r=await api('cancel-order',{receipt:el.dataset.code});if(r.blocked){$('#my-order-result').innerHTML='<section class="panel"><h2>订单已取消</h2><p class="error">此网络已连续取消3次订单，访问已被限制。请联系管理员解除封锁。</p></section>';}else{await lookup(el.dataset.code);toast('订单已取消');}}catch(err){toast(err.message);}finally{el.disabled=false;}}
  if(action==='reject-order'){const dialog=$('#reject-dialog');const form=$('#reject-order-form');form.elements.order_id.value=id;form.elements.reason.value='';$('#form-error').textContent='';dialog.showModal();form.elements.reason.focus();}
  if(action==='close-reject')$('#reject-dialog').close();
  if(action==='fulfill'&&confirm('确认此订单已经配送完成？')){el.disabled=true;try{await api('fulfill-order',{id});await renderOrders();toast('订单已完成');}catch(err){toast(err.message);el.disabled=false;}}
  if(action==='unblock'&&confirm('确定解除此网络的访问限制，并清零连续取消次数？')){el.disabled=true;try{await api('unblock-ip',{ip_hash:el.dataset.ip});await renderRules();toast('已解除封锁');}catch(err){toast(err.message);el.disabled=false;}}
  if(action==='my-orders')location.hash='orders';
  if(action==='lookup'){el.disabled=true;try{await lookup(el.dataset.code);}catch(err){toast(err.message);}finally{el.disabled=false;}}
  if(action==='forget-orders'&&confirm('清除后需手动输入查询码，请确认已妥善保存。继续清除？')){localStorage.removeItem('market-receipts');myOrders();}
  if(action==='logout')logout();
  if(action==='password')passwordForm();
  if(action==='back-admin')admin();
  if(action==='clear-cart'&&confirm('确定清空菜篮中的所有商品？')){cart={};saveCart();checkout();}
  if(action==='refresh'){el.disabled=true;try{await renderOrders();}catch(err){toast(err.message);el.disabled=false;}}
  if(action==='cancel-edit')$('#product-dialog').close();
  if(action==='new-product')openProductEditor();
  if(action==='edit-product')openProductEditor(products.find(p=>p.id===id));
  if(action==='delete-product'&&confirm('确定删除该商品？历史订单将保留。')){el.disabled=true;try{await api('delete-product',{id});products=(await api('products')).products;renderProductAdmin();toast('商品已删除');}catch(err){toast(err.message);el.disabled=false;}}
});
document.addEventListener('submit',async e=>{
  e.preventDefault();const f=e.target,formId=f.getAttribute('id'),data=Object.fromEntries(new FormData(f)),button=f.querySelector('[type=submit]'),error=$('#form-error');if(!button)return;const buttonText=button.textContent;button.disabled=true;if(error)error.textContent='';
  try{
    if(formId==='login-form'){const r=await api('login',data);token=r.token;sessionStorage.setItem('market-token',token);staff=r;tab='orders';if(!staff.must_change)products=(await api('products')).products;await admin();}
    if(formId==='password-form'){if(data.password!==data.confirm)throw new Error('两次输入的新密码不一致');await api('password',data);logout();toast('密码修改成功，请使用新密码登录');}
    if(formId==='lookup-form')await lookup(data.receipt);
    if(formId==='reject-order-form'){const reason=data.reason.trim();if(!reason)throw new Error('请填写拒绝配送原因');await api('reject-order',{id:data.order_id,reason});$('#reject-dialog').close();await renderOrders();toast('订单已拒绝配送，客户可查看原因');}
    if(formId==='order-search-form'){orderSearch=data.query.trim();if(orderSearch)statusFilter='';await renderOrders();}
    if(formId==='order-form'){
      pendingId ||= crypto.randomUUID();pendingReceipt ||= receiptCode();const code=pendingReceipt;if(!fx)throw new Error('请先刷新汇率');const submitted=await api('order',{...data,id:pendingId,receipt:code,fx_rate:fx.rate,fx_date:fx.date,items:lines().map(p=>({id:p.id,quantity:cart[p.id],unit_price_cents:p.price_cents}))});rememberReceipt(code);cart={};saveCart();$('#main').innerHTML=`<section class="panel success"><div class="success-icon">✓</div><h1>采购需求已提交</h1><p class="muted">供应商将通过您填写的联系方式确认供货和配送。<br>请截图或复制保存专属查询码。</p><p style="font-size:27px;letter-spacing:3px;font-weight:700">${esc(formatCode(code))}</p><div class="order-total"><span>订单合计</span><div>${dual(submitted.total_mxn_cents,submitted.total_cny_cents)}</div></div><p class="muted">下单汇率：${submitted.fx_rate} CNY / MXN · ${esc(submitted.fx_date)}</p><div class="notice">配送区域：${esc(data.region)}<br>查询码已自动保存在此浏览器，请勿分享给他人。</div><button class="primary" data-action="my-orders">查看我的订单 →</button><p><a href="#shop" class="muted">继续逛逛菜市场</a></p></section>`;
    }
    if(formId==='product-form'){const payload=new FormData(f);const image=payload.get('image');if(image?.size>5*1024*1024)throw new Error('图片不能超过5MB');if(image?.size&&!['image/jpeg','image/png','image/webp'].includes(image.type))throw new Error('仅支持 JPG、PNG 或 WebP 图片');button.textContent='正在保存…';await api('save-product',payload);$('#product-dialog').close();products=(await api('products')).products;renderProductAdmin();toast('商品已保存');}
    if(formId==='supplier-form'){if(!confirm('保存后供应商需要使用本次设置的初始密码重新登录，确定继续？'))return;await api('save-supplier',data);await renderSupplier();toast('供应商账号已保存');}
  }catch(err){const message=err.name==='TimeoutError'?'请求超时，请检查网络后重试':err.message;if(error?.isConnected)error.textContent=message;else toast(message);}finally{button.disabled=false;button.textContent=buttonText;}
});
window.addEventListener('hashchange',route);
async function boot(){try{fx=await api('fx');}catch{fx=null;}if(location.hash==='#admin'){try{if(token)staff=await api('me');products=(await api('products')).products;}catch{}route();return;}try{products=(await api('products')).products;for(const id of Object.keys(cart))if(!products.some(p=>p.id===id)||!Number.isInteger(cart[id])||cart[id]<1||cart[id]>999)delete cart[id];saveCart();if(token){try{staff=await api('me');}catch{logout();}}route();}catch(e){$('#main').innerHTML=`<section class="panel"><h1>暂时无法加载菜市场</h1><p class="error">${esc(e.message)}</p><button onclick="location.reload()">重新加载</button></section>`;}}
boot();
